message:
Removes nested type for text/signature in reasoning_content. (#438)
Fixes #432
Here is the sample test code from #432.
```python
import asyncio
from langchain_aws import ChatBedrockConverse
from langchain_core.tools import tool
from langgraph.prebuilt import create_react_agent
prompt = """
You are a helpful assistant used for debugging.
You will say short messages to reply when I ask, or use your fake tool when I ask you to.
"""
model = ChatBedrockConverse(
model="us.anthropic.claude-3-7-sonnet-20250219-v1:0",
max_tokens=5000,
region_name="us-east-1",
additional_model_request_fields={
"thinking": {"type": "enabled", "budget_tokens": 2000}
},
)
@tool
def fake_tool(fake_input_1: str, fake_input_2: int) -> str:
"this is fake tool, only use it when requested"
return "fake_output"
agent = create_react_agent(model, [fake_tool], prompt=prompt, name="Debug_Agent")
async def main():
async for stream_response_type, response_data in agent.astream(
input={"messages": [{"role": "user", "content": "hi"}]},
config={"configurable": {"thread_id": "1"}},
stream_mode=["debug", "messages"],
):
if stream_response_type == "debug" and response_data.get("type") == "task_result":
print(response_data["payload"]["result"][0][1][0].content)
asyncio.run(main())
```
